parameters.text:
=Traduis le titre en français si nécessaire. Rédige aussi un résumé fidèle et informatif de l'article ci-dessous, en français, en 3 à 5 phrases : couvre les points clés de l'article dans son ensemble (pas seulement l'introduction), garde le ton original.

Titre : {{ $json.titre }}

Article : {{ $json.article ? $json.article.slice(0, 6000) : $json["Résumé (Content)"] }}

Format de sortie STRICT, exactement 2 lignes, rien d'autre (pas de JSON, pas de markdown, pas de labels) :
Ligne 1 : le titre traduit en français
Ligne 2 : le résumé en français (plusieurs phrases sur cette seule ligne)

parameters.jsCode:
const rawText = $json.data || "";
const match = rawText.match(/Markdown Content:\n([\s\S]*)/i);
const cleanedBody = match ? match[1].trim() : rawText.trim();
const { data, ...rest } = $json;
return { json: { ...rest, cleanedBody } };

const items = $input.all().map(item => item.json);

const format = (arr) => arr.map(item => `${item.ref} - ${item.nom}`).join('\n');

const themes = items.filter(item => item.type === 'thème');
const secteurs = items.filter(item => item.type === 'secteur');
const metiers = items.filter(item => item.type === 'métier');

return [{
  json: {
    contexte_themes: format(themes),
    contexte_secteurs_metiers: `SECTEURS :\n${format(secteurs)}\n\nMÉTIERS :\n${format(metiers)}`
  }
}];

// 1. On récupère notre catalogue de référence généré au début du workflow
// Assure-toi que le nom du nœud entre guillemets est bien exact.
const catalogue = $items("Normaliser catégories");
const result = [];

// 2. On boucle sur tous les éléments (tes paires infos_id / categorie_id)
for (const item of $input.all()) {
  const infoId = item.json.infos_id;

  // On récupère le numéro que l'IA a donné
  const codeIA = item.json.categorie_id; 

  // 3. Le filtre anti-plantage : si l'IA a répondu 0 (hors sujet) 
  // ou que c'est vide, on ignore cette ligne pour ne pas casser Supabase.
  if (codeIA === 0 || !codeIA) {
    console.log(`Code ignoré pour l'article ${infoId}`);
    continue; 
  }

  // 4. La recherche : On parcourt le catalogue pour trouver la ligne 
  // dont la "ref" correspond au numéro de l'IA.
  const categorieCorrespondante = catalogue.find(cat => cat.json.ref === codeIA);

  // 5. La création de la ligne finale
  if (categorieCorrespondante) {
    result.push({
      json: {
        infos_id: infoId,
        // On remplace le numéro par le vrai UUID trouvé dans le catalogue
        categorie_id: categorieCorrespondante.json.id 
      }
    });
  } else {
    // Si l'IA a halluciné un chiffre qui n'existe pas (ex: 99)
    console.log(`Attention: Le code ${codeIA} n'existe pas dans la base.`);
  }
}

// 6. On retourne la liste propre
return result;

const connus = new Set(
  $('Sujets déjà connus').all().map(item => item.json.lien)
);

return $input.all().filter(item => item.json.link !== undefined && !connus.has(item.json.link));

const infosExistantes = new Set(
  $input.all().filter(i => i.json.sujet_veille_id !== undefined).map(i => i.json.sujet_veille_id)
);

return $input.all().filter(item =>
  item.json.lien !== undefined &&
  item.json["Score (AI)"] >= 5 &&
  !infosExistantes.has(item.json.id) &&
  (item.json.tentatives_scraping || 0) < 3
);

const themesResults = $('Categories').all();
const autresResults = $('Categories Secteur Metier').all();

return themesResults.map((item, i) => {
  const themesOutput = item.json.output || {};
  const autresOutput = (autresResults[i] && autresResults[i].json.output) || {};

  const themes = themesOutput['catégories'] || [];
  const autres = autresOutput['catégories'] || [];

  return {
    json: {
      categories: [...new Set([...themes, ...autres])],
      commentaire_theme: themesOutput.commentaire || null,
      commentaire_secteur_metier: autresOutput.commentaire || null
    },
    pairedItem: { item: i }
  };
});

const raw = ($json.text || "").trim();
const lines = raw.split("\n").map(l => l.trim()).filter(Boolean);
const score = parseFloat((lines[0] || "0").replace(",", ".")) || 0;
const justification = lines.slice(1).join(" ").trim();
return { json: { ...$json, score, justification } };

const raw = ($json.text || "").trim();
const lines = raw.split("\n").map(l => l.trim()).filter(Boolean);
const titre = lines[0] || "";
const resume = lines.slice(1).join(" ").trim();
return { json: { output: { titre, "Résumé (Content)": resume } } };

const raw = ($json.text || "").trim();
const lines = raw.split("\n").map(l => l.trim()).filter(Boolean);
const idsLine = (lines[0] || "").toLowerCase();
const commentaire = lines.slice(1).join(" ").trim();
const categories = (idsLine === "vide" || idsLine === "")
  ? []
  : idsLine.split(",").map(s => parseInt(s.trim(), 10)).filter(n => !isNaN(n));
return { json: { output: { "catégories": categories, commentaire } } };

